const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');
const output=process.env.DEEP_LABEL_OUTPUT||'.superpowers/deep-audit/visible-labels';
async function main(){const {createServer}=await import('vite');const server=await createServer({cacheDir:'.superpowers/visible-label-cache',server:{host:'127.0.0.1',port:4457,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const results=[];fs.mkdirSync(output,{recursive:true});const axe=fs.readFileSync(require.resolve('axe-core/axe.min.js'),'utf8');
try{for(const language of (process.env.DEEP_LABEL_SMOKE?['English + Bangla']:['English','English + Bangla','Bangla']))for(const width of (process.env.DEEP_LABEL_SMOKE?[1440]:[390,1440]))for(const theme of ['light','dark']){
 const bn=language==='Bangla',id=[language.replace(/\W/g,'-'),width,theme].join('-');const context=await browser.newContext({viewport:{width,height:width===390?844:900},hasTouch:width===390,colorScheme:theme,reducedMotion:'reduce'});await context.route('https://fonts.googleapis.com/**',r=>r.abort());await context.addInitScript(({language,theme})=>{if(location.protocol!=='http:')return;localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({language,mode:'Simple',density:'Compact',terminology:'simple',dateView:'transaction'}));},{language,theme});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 async function scan(state){await page.addScriptTag({content:axe});const r=await page.evaluate(async()=>{const r=await axe.run(document,{runOnly:['label-content-name-mismatch']});return r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}));});results.push({language,width,theme,state,violations:r});return r;}
 try{await page.goto('http://127.0.0.1:4457/#/app/dashboard',{waitUntil:'domcontentloaded'});await page.locator('main h1').waitFor();
 const shell=await scan('workspace');assert.deepEqual(shell,[],'Visible user/sidebar labels must be included in names');
 if(width===390){await page.getByRole('button',{name:bn?'ERP মেনু খুলুন':'Open ERP navigation',exact:true}).tap();const drawer=page.getByRole('dialog',{name:bn?'ERP মেনু':'ERP navigation',exact:true});await expect(drawer).toBeVisible();assert.deepEqual(await scan('mobile-navigation'),[]);await drawer.getByRole('button',{name:bn?'মেনু বন্ধ করুন':'Close navigation',exact:true}).tap();await expect(drawer).toHaveCount(0);}
 else{const nav=page.getByRole('navigation',{name:bn?'মূল মেনু':'Main',exact:true});const group=nav.locator('button[aria-controls]').first();await group.focus();await group.press('Enter');await expect(group).toHaveAttribute('aria-expanded','true');await group.press('Enter');await expect(group).toHaveAttribute('aria-expanded','false');}
 const user=page.getByRole('button',{name:bn?/^ব্যবহারকারীর মেনু/:/^User menu/});await user.click();await expect(user).toHaveAttribute('aria-expanded','true');await page.keyboard.press('Escape');await expect(user).toHaveAttribute('aria-expanded','false');await expect(user).toBeFocused();
 await page.goto('http://127.0.0.1:4457/#/app/purchases/new',{waitUntil:'domcontentloaded'});const tile=page.getByRole('button',{name:/^Quick add LED Bulb 12W(?:\s|$)/});await tile.waitFor();const purchase=await scan('purchase-quick-items');assert.deepEqual(purchase,[],'Quick add names include visible product and price');if(width===390)await tile.tap();else await tile.click();await expect(page.getByTestId('purchase-cart-row')).toHaveCount(1);await expect(page.getByTestId('purchase-cart-row')).toContainText('LED Bulb 12W');assert.deepEqual(errors,[]);results.push({language,width,theme,state:'interactions',status:'passed'});
 }catch(e){console.error(id,e.message);results.push({language,width,theme,state:'interactions',status:'failed',error:e.message});await page.screenshot({path:output+'/'+id+'.png',fullPage:true});}
 const failed=results.at(-1).status==='failed';await context.tracing.stop(failed?{path:output+'/'+id+'-trace.zip'}:{});await context.close();console.log(id,failed?'failed':'passed');
}}finally{fs.writeFileSync(output+'/results.json',JSON.stringify(results,null,2));await browser.close();await server.close();}assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1;});
